UPDATE plants SET sustainable_alternatives = 'Variétés landrace modernes certifiées. Conservation ex situ dans des banques de graines (Vavilov Institute, USDA).' WHERE id IN (870010, 870001, 870009, 870007, 870005, 870011) AND (sustainable_alternatives IS NULL OR sustainable_alternatives = 'NULL');

UPDATE plants SET sustainable_alternatives = 'Tabac Perique de Saint-James Parish (Louisiane). Fermentation anaérobie d\'autres variétés de tabac burley.' WHERE id = 840003 AND (sustainable_alternatives IS NULL OR sustainable_alternatives = 'NULL');

UPDATE plants SET sustainable_alternatives = 'Tabac oriental de Grèce et Turquie (Basma, Izmir). Tabac Latakia pour les notes fumées.' WHERE id = 810025 AND (sustainable_alternatives IS NULL OR sustainable_alternatives = 'NULL');

UPDATE plants SET sustainable_alternatives = 'Épicéa noir de culture certifiée FSC. Épicéa de Sibérie (Picea obovata). Sapin baumier (Abies balsamea).' WHERE id = 660756 AND (sustainable_alternatives IS NULL OR sustainable_alternatives = 'NULL');

UPDATE plants SET sustainable_alternatives = 'Tabac oriental Yaka et Basma. Tabac Latakia fumé pour les notes similaires.' WHERE id = 810024 AND (sustainable_alternatives IS NULL OR sustainable_alternatives = 'NULL');

UPDATE plants SET sustainable_alternatives = 'Variétés landrace afghanes modernes. Conservation ex situ (banques de graines). Kush himalayens apparentés.' WHERE id IN (870004, 870008, 870003) AND (sustainable_alternatives IS NULL OR sustainable_alternatives = 'NULL');

SELECT id, name, conservation_status, sustainable_alternatives FROM plants WHERE conservation_status IN ('CR', 'EN') AND sustainable_alternatives IS NOT NULL ORDER BY conservation_status, name;

